"""Portable exact audit of the new four adjoint obstructions.

Uses only Python's standard library. This checks finite algebra identities,
not the cited geometric residue/localization theorem and not Lean acceptance.
"""
from fractions import Fraction as Q
from pathlib import Path
import ast,json,sys
BASE=Path(__file__).resolve().parent

def clean(p):return {e:c for e,c in p.items() if c}
def read(entries):
 out={}
 for e,c in entries:
  e=tuple(e);out[e]=out.get(e,Q(0))+Q(c)
 return clean(out)
def add(p,q):
 out=dict(p)
 for e,c in q.items():out[e]=out.get(e,Q(0))+c
 return clean(out)
def scale(p,c):return clean({e:v*c for e,v in p.items()})
def mul(p,q):
 out={}
 for e,c in p.items():
  for f,d in q.items():
   a=tuple(x+y for x,y in zip(e,f));out[a]=out.get(a,Q(0))+c*d
 return clean(out)
def deriv(p,i):
 out={}
 for e,c in p.items():
  if e[i]:
   f=list(e);f[i]-=1;out[tuple(f)]=c*e[i]
 return clean(out)
def shift(p,e):return {tuple(a+b for a,b in zip(f,e)):c for f,c in p.items()}
def lift(p):return {(0,)+e:c for e,c in p.items()}
def power(p,n):
 r={(0,)*len(next(iter(p))):Q(1)}
 for _ in range(n):r=mul(r,p)
 return r

def monomials(n,d):
 if n==1:
  yield (d,);return
 for a in range(d+1):
  for e in monomials(n-1,d-a):yield (a,)+e

def scalar_audit(target):
 """Independent verification of the exact data supplied by benediamond."""
 path=BASE/'contact_obstruction.json'
 if not path.exists():path=BASE.parent/'off-paired-contact-obstruction-2026-10-22/contact_obstruction.json'
 data=json.loads(path.read_text())
 def rp(a):return read([(x['exponents'],x['coefficient']) for x in a])
 H={(6,0,0,0):Q(1),(0,6,0,0):Q(1),(0,0,6,0):Q(1),(0,0,0,6):Q(1),(3,1,1,1):Q(1,2)}
 C={(0,3,0,1):Q(1,2),(2,1,1,0):Q(1,3)}
 A={(3,0,3,0):Q(1)}
 assert data['variables']==['w','x','y','z'] and rp(data['H'])==H
 # Bind to the physical target using a restricted arithmetic AST, never eval.
 names=['X0','X1','X2','Y0','Y1','Y2'];zero=(0,)*6
 def parse(n):
  if isinstance(n,ast.Constant) and type(n.value) is int:return {zero:Q(n.value)}
  if isinstance(n,ast.Name) and n.id in names:
   e=[0]*6;e[names.index(n.id)]=1;return {tuple(e):Q(1)}
  if isinstance(n,ast.UnaryOp) and isinstance(n.op,ast.USub):return scale(parse(n.operand),-1)
  assert isinstance(n,ast.BinOp)
  a=parse(n.left)
  if isinstance(n.op,ast.Pow):
   assert isinstance(n.right,ast.Constant) and type(n.right.value) is int and n.right.value>=0
   return power(a,n.right.value)
  b=parse(n.right)
  if isinstance(n.op,ast.Add):return add(a,b)
  if isinstance(n.op,ast.Sub):return add(a,scale(b,-1))
  if isinstance(n.op,ast.Mult):return mul(a,b)
  assert isinstance(n.op,ast.Div) and set(b)=={zero} and b[zero]
  return scale(a,1/b[zero])
 lines=target.read_text().splitlines()
 def field(k):
  vals=[x[len(k)+2:] for x in lines if x.startswith(k+': ')]
  assert len(vals)==1;return vals[0]
 assert field('id')=='off-paired' and field('q')=='1'
 def embed(p):return {(e[0],e[1],0,e[2],e[3],0):c for e,c in p.items()}
 F=add(embed(H),shift(embed(C),(0,0,1,0,0,1)))
 F=add(F,{(0,0,6,0,0,0):Q(1),(0,0,0,0,0,6):Q(1)})
 assert parse(ast.parse(field('F'),mode='eval').body)==F
 assert parse(ast.parse(field('A'),mode='eval').body)==embed(A)
 print('PASS: scalar family and source bound to the actual immutable target')
 full=mul(A,power(C,5))
 projected={e:c for e,c in full.items() if (e[1]-e[3])%6==0 and (e[2]-e[3])%6==0}
 assert projected==rp(data['projected_source'])=={(11,7,7,1):Q(5,162)}
 gradient=[deriv(H,i) for i in range(4)];current=projected
 assert len(data['steps'])==2
 for step,pole in zip(data['steps'],[5,4]):
  assert step['pole']==pole and rp(step['source'])==current
  assert len(step['multipliers'])==4
  combo={};div={}
  for i,raw in enumerate(step['multipliers']):
   m=rp(raw);combo=add(combo,mul(m,gradient[i]));div=add(div,deriv(m,i))
  assert combo==current
  current=scale(div,Q(1,pole-1));assert current==rp(step['reduced'])
  assert all(sum(e)==6*(pole-1)-4 for e in current)
 rem=rp(data['final_remainder']);combo={}
 assert len(data['final_jacobian_multipliers'])==4
 for i,raw in enumerate(data['final_jacobian_multipliers']):combo=add(combo,mul(rp(raw),gradient[i]))
 assert add(combo,rem)==current
 functional=rp(data['cokernel_witness'])
 def pairing(p):return sum((c*functional.get(e,Q(0)) for e,c in p.items()),Q(0))
 count=0
 for e in monomials(4,9):
  for g in gradient:
   assert pairing(shift(g,e))==0;count+=1
 assert count==880 and functional[(2,4,4,4)]==1
 value=Q(data['pairing'])
 assert value==Q(-54190940,990659911761) and pairing(current)==value
 assert rem=={(2,4,4,4):value}
 print('PASS: both exact scalar pole reductions, final Jacobian reduction, and all 880 dual relations')
 print('PASS: nonzero residue pairing',value)

def main():
 c=json.loads((BASE/'all_directions_certificate.json').read_text())
 assert c['basis_powers']==[0,1,3,4]
 js=c['basis_powers'];K=read(c['common_denominator'])
 assert K=={(1,6):Q(16),(5,0):Q(-2916)}
 f=read(c['curve'])
 assert f=={(0,2,0):Q(1),(1,1,1):Q(2),(2,0,2):Q(1),(6,0,0):Q(-4)}
 matrices={key:[[read(p) for p in row] for row in vals] for key,vals in c['connection_numerators'].items()}
 # Verify the original differential reductions, without trusting a connection generator.
 for name,idx in [('H',1),('C',2)]:
  mat=matrices[name]
  for j,powj in enumerate(js):
   N=scale(shift(deriv(f,idx),(powj,0,0)),Q(-1,2))
   S=read(c['correction_numerators'][name][j]);R={}
   for i,powi in enumerate(js):R=add(R,shift(lift(mat[i][j]),(powi,0,0)))
   rhs=add(add(mul(R,f),mul(deriv(S,0),f)),scale(mul(S,deriv(f,0)),Q(-1,2)))
   assert mul(lift(K),N)==rhs,(name,powj)
 print('PASS: all eight exact genus-two differential reduction identities')
 H,C={(1,0):Q(1)},{(0,1):Q(1)}
 for i in range(4):
  for j in range(4):
   lhs=add(scale(mul(H,matrices['H'][i][j]),3),scale(mul(C,matrices['C'][i][j]),2))
   assert lhs==scale(K,[-2,-1,1,2][j] if i==j else 0)
 print('PASS: exact Euler identity and the fixed compact basis')
 for omitted,row in enumerate(c['adjoint_rows']):
  assert row['omitted_basis_power']==js[omitted]
  L=[read(x) for x in row['L']]
  RH,RC=read(row['R_H']),read(row['R_C'])
  assert RH and RC
  assert add(scale(mul(H,RH),3),scale(mul(C,RC),2))=={}
  for name,idx,R in [('H',0,RH),('C',1,RC)]:
   for j in range(4):
    lhs=mul(K,deriv(L[j],idx))
    for i in range(4):lhs=add(lhs,scale(mul(L[i],matrices[name][i][j]),-1))
    assert lhs==(mul(K,R) if j==omitted else {}),(omitted,name,j)
  source={}
  for i in range(4):source=add(source,scale(mul(L[i],matrices['H'][i][0]),Q(-1,6)))
  T={(-5,5):Q(1)}
  assert read(row['source_without_A'])==T
  assert source==mul(K,T)
  print('PASS: omitted power',js[omitted],': adjoint defects have only this column; source is C^5/H^5')
 target=Path(sys.argv[1]) if len(sys.argv)>1 else (BASE/'instance.rec' if (BASE/'instance.rec').exists() else BASE.parent/'target/instance.rec')
 scalar_audit(target)
 print('PASS: new identities plus the prior exact nonzero residue certificate.')
 print('Conclusion, with the cited geometric step: every compact-module solution must have')
 print('2 C U_j(H) - 3 H U_j(C) != 0 for EACH j = 0,1,3,4, even after finite extension.')
 print('This is a necessary condition, not a solution or unrestricted nonexistence claim.')
if __name__=='__main__':main()
